143: // RestartCNIPod locates and deletes the local CNI DaemonSet pod on the target node.
144: func (r *Remediator) RestartCNIPod(ctx context.Context, nodeName, daemonSetName, namespace string) (string, error) {
145: 	log := logf.FromContext(ctx).WithName("remediator")
146: 
147: 	podList := &corev1.PodList{}
148: 	if err := r.Client.List(ctx, podList, client.InNamespace(namespace)); err != nil {
149: 		return "", fmt.Errorf("failed to list pods in namespace %s: %w", namespace, err)
150: 	}
151: 
152: 	var targetPod *corev1.Pod
153: 	for _, pod := range podList.Items {
154: 		if pod.Spec.NodeName != nodeName {
155: 			continue
156: 		}
157: 		// Match against daemonSetName (calico-node, kindnet, etc.)
158: 		if strings.Contains(pod.Name, daemonSetName) || strings.Contains(pod.Name, "calico-node") || strings.Contains(pod.Name, "kindnet") {
159: 			targetPod = &pod
