179: 
180: 	node := &corev1.Node{}
181: 	if err := r.Client.Get(ctx, client.ObjectKey{Name: nodeName}, node); err != nil {
182: 		return fmt.Errorf("failed to get node %s: %w", nodeName, err)
183: 	}
184: 
185: 	patch := client.MergeFrom(node.DeepCopy())
186: 
187: 	if cordon && !node.Spec.Unschedulable {
188: 		log.Info("Cordoning degraded node", "node", nodeName)
