197: 			taintExists = true
198: 			break
199: 		}
200: 	}
201: 
202: 	if !taintExists {
203: 		log.Info("Adding network-degraded taint to node", "node", nodeName, "key", taintKey, "effect", taintEffect)
204: 		node.Spec.Taints = append(node.Spec.Taints, corev1.Taint{
205: 			Key:    taintKey,
206: 			Value:  taintValue,
207: 			Effect: effect,
208: 		})
209: 	}
